```ts
declare const tools: { mcp__treecontext__treecontext_insert(args: {
  // The text to store. Be specific — vague entries produce poor summaries. Up to 50000 characters, except a checkpoint under a run's key, which the checkpoint cap governs instead.
  content: string;
  // When true, this node is protected from retention eviction and demotion — it is never archived away or shrunk by the storage valve.
  decay_exempt?: boolean;
  // Reference pointer to non-text content. The content field must contain a text description of the media; the actual binary lives at the URI.
  media_ref?: {
  extension?: string;
  // Extracted metadata: dimensions, codec, duration, GPS, etc.
  extracted?: { [key: string]: unknown; };
  filename?: string;
  // MIME type (image/png, audio/wav, etc.)
  mime_type: string;
  size_bytes?: number;
  // URI to the content (file://, https://, etc.)
  uri: string;
};
  // Optional structured metadata dict for filtering during queries. refs: the id (or ids) of earlier entries this one responds to; they then show it as referencedBy, and the earlier entries stay untouched. brief_for: a worktree name or subagent role this entry briefs; a session starting in that worktree is handed it, and a subagent of that role finds it in its default search. The writer is stamped by the store and said back as writer. kind "checkpoint" with run and key is numbered by the store when it lands. kind "run-open" or "run-close" with run records the run's open or close as the harness does, by this writer; a close takes its reason from reason, else from content.
  metadata?: { [key: string]: unknown; };
  // Node IDs whose resume-pointer flags this insert supersedes (e.g. a prior plan or close-out this entry replaces). Clears next_session, demotes status "active" to "superseded", and writes a superseded_by trace on each target. Targets stay fully queryable. A target another writer wrote is never changed: it is recorded in this entry's refs instead and listed as referenced. A client the server cannot place may retire a chapter written before the store recorded writers, where no session has run in the main checkout; the retirement is recorded on both entries and listed as retired_across.
  supersedes?: Array<string>;
}): Promise<CallToolResult>; };
```"}]

